public int paintersPartition(int[] boards, int k) {
    int lo = 0, hi = 0;
    for (int b : boards) { lo = Math.max(lo, b); hi += b; }
    for (int x = lo; x <= hi; x++) {
        if (paintersNeeded(boards, x) <= k) {
            return x;          // first feasible time is the minimum
        }
    }
    return hi;
}

private int paintersNeeded(int[] boards, int timeCap) {
    int painters = 1, load = 0;
    for (int b : boards) {
        if (load + b > timeCap) {
            painters++;        // hand this board to a new painter
            load = b;
        } else {
            load += b;
        }
    }
    return painters;
}

