public int paintersPartition(int[] boards, int k) {
    int lo = 0, hi = 0;
    for (int b : boards) { lo = Math.max(lo, b); hi += b; }
    int ans = hi;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (paintersNeeded(boards, mid) <= k) {
            ans = mid;        // feasible → remember it, try LESS time
            hi = mid - 1;
        } else {
            lo = mid + 1;     // infeasible → allow MORE time
        }
    }
    return ans;
}

